function setNative(el,value){var proto=(el instanceof HTMLTextAreaElement)?HTMLTextAreaElement.prototype:HTMLInputElement.prototype;var setter=Object.getOwnPropertyDescriptor(proto,'value');if(setter&&setter.set)setter.set.call(el,value);el.dispatchEvent(new Event('input',{bubbles:true}));el.dispatchEvent(new Event('change',{bubbles:true}));}
function pad2(n){n=String(n);return n.length<2?'0'+n:n;}
function otpUp(){
  var body=(document.body?document.body.innerText:'')||'';
  if(/verification code|enter your code|we've sent your code|we sent your code|secure.?code|you've got mail/i.test(body)) return true;
  var el=Array.prototype.find.call(document.querySelectorAll('input'), function(e){ return vis(e) && /otp|code|verification/i.test((e.name||'')+' '+(e.id||'')+' '+(e.placeholder||'')+' '+(e.autocomplete||'')); });
  return !!el;
}
function pxCaptcha(){ return !!document.querySelector('#px-captcha') || /robot or human|press and hold/i.test((document.body?document.body.innerText:'')||''); }
function existing(){
  var body=(document.body?document.body.innerText:'')||'';
  return /welcome back|already have an account|that email is already|already registered/i.test(body);
}
var DOB='{{identity.dob}}';
var dp=String(DOB).split('-'); var dobY=dp[0]||'1990'; var dobM=String(parseInt(dp[1]||'1',10)); var dobD=String(parseInt(dp[2]||'1',10));
var MNAMES=['january','february','march','april','may','june','july','august','september','october','november','december'];
function lbl(el){ return ((el.name||'')+' '+(el.id||'')+' '+(el.placeholder||'')+' '+(el.autocomplete||'')+' '+(el.getAttribute('aria-label')||'')+' '+(el.getAttribute('data-test')||'')+' '+(el.getAttribute('data-testid')||'')+' '+(el.getAttribute('data-test-id')||'')).toLowerCase(); }
function setSel(sel,num,isMonth){
  var want=String(num); var pad=pad2(num); var opts=Array.prototype.slice.call(sel.options);
  for(var i=0;i<opts.length;i++){ var o=opts[i]; var v=String(o.value||'').trim().toLowerCase(); var t=String(o.text||'').trim().toLowerCase(); if(!v&&!t)continue;
    if(isMonth){ if(v===want||v===pad||t===want||t===pad||t.indexOf(MNAMES[num-1])>=0){ sel.value=o.value; sel.dispatchEvent(new Event('change',{bubbles:true})); sel.dispatchEvent(new Event('input',{bubbles:true})); return true; } }
    else if(v===want||v===pad||t===want||t===pad){ sel.value=o.value; sel.dispatchEvent(new Event('change',{bubbles:true})); sel.dispatchEvent(new Event('input',{bubbles:true})); return true; } }
  return false;
}
function birthdayUp(){
  var body=(document.body?document.body.innerText:'')||'';
  var hasText=/date of birth|birthday|when.{0,20}born|your birth|tell us about yourself|how old/i.test(body);
  var sels=Array.prototype.filter.call(document.querySelectorAll('select'), vis);
  var inputs=Array.prototype.filter.call(document.querySelectorAll('input'), vis);
  function find(els,re){ return Array.prototype.find.call(els, function(e){ return re.test(lbl(e)); }); }
  var mS=find(sels,/month|\bmm\b/), dS=find(sels,/\bday\b|\bdd\b/), yS=find(sels,/year|\byyyy\b/);
  var mI=find(inputs,/month|\bmm\b/), dI=find(inputs,/\bday\b|\bdd\b/), yI=find(inputs,/year|\byyyy\b/);
  var dateI=find(inputs,/birth|\bdob\b|date.of.birth/);
  var hasFields=(mS&&dS&&yS)||(mI&&dI&&yI)||dateI;
  if(!hasText && !hasFields) return false;
  var ok=false;
  if(mS&&dS&&yS){ ok=setSel(mS,dobM,true)&&setSel(dS,dobD,false)&&setSel(yS,dobY,false); }
  if(!ok && mI&&dI&&yI){ setNative(mI,dobM); setNative(dI,dobD); setNative(yI,dobY); ok=true; }
  if(!ok && dateI){ var it=(dateI.type||'').toLowerCase(); setNative(dateI, it==='date' ? (dobY+'-'+pad2(dobM)+'-'+pad2(dobD)) : (pad2(dobM)+'/'+pad2(dobD)+'/'+dobY)); ok=true; }
  if(!ok) return 'seen';
  var btn=Array.prototype.find.call(document.querySelectorAll('button'), function(b){ return vis(b) && /continue|next|submit|save|verify|done|confirm|add/i.test(b.innerText||''); });
  if(btn){ try{btn.click();}catch(e){} }
  return 'filled';
}
function describeFields(){
  var out=[]; var sels=Array.prototype.filter.call(document.querySelectorAll('select'), vis);
  for(var i=0;i<sels.length&&out.length<8;i++){ out.push('select['+lbl(sels[i]).trim().split(/\s+/).slice(0,3).join(' ')+']'); }
  var inputs=Array.prototype.filter.call(document.querySelectorAll('input'), vis);
  for(var j=0;j<inputs.length&&out.length<8;j++){ out.push('input['+lbl(inputs[j]).trim().split(/\s+/).slice(0,3).join(' ')+']'); }
  return out.join(', ')||'no fields';
}
var deadline=Date.now()+60000;
var bdaySeen=false;
while(Date.now()<deadline){
